// hotel.checkin → onboarding message in all LSH languages.
const b = $input.first().json.body || {};
const d = b.data || {};
const guest = d.guest ? (', ' + d.guest) : '';
const room = d.room || '—';
const checkin = new Date(d.checkedInAt || Date.now());
const out = new Date(checkin.getTime() + (Number(d.nights) || 0) * 86400000);
const date = out.toISOString().slice(0, 10);
const CITY = "Katowice";
const PORTAL = "https://guestportal.pl";
const T = {
  en: 'Welcome' + guest + '! Your room ' + room + ' is ready. Check-out: ' + date + '. Wi-Fi and door code: see the guest portal ' + PORTAL + '. Room service: dial 0 or scan the in-room QR menu. Need anything? Just reply. Enjoy your stay in ' + CITY + '!',
  pl: 'Witamy' + guest + '! Pokój ' + room + ' jest gotowy. Wymeldowanie: ' + date + '. Wi-Fi i kod do drzwi: w portalu gościa ' + PORTAL + '. Room service: wybierz 0 lub zeskanuj kod QR w pokoju. Potrzebujesz czegoś? Napisz. Udanego pobytu w ' + CITY + '!',
  de: 'Willkommen' + guest + '! Ihr Zimmer ' + room + ' ist bereit. Check-out: ' + date + '. WLAN und Türcode: im Gästeportal ' + PORTAL + '. Zimmerservice: Wählen Sie 0 oder scannen Sie den QR-Code im Zimmer. Brauchen Sie etwas? Antworten Sie einfach. Schönen Aufenthalt in ' + CITY + '!',
  fr: 'Bienvenue' + guest + ' ! Votre chambre ' + room + ' est prête. Départ : ' + date + '. Wi-Fi et code de porte : sur le portail client ' + PORTAL + '. Room service : composez le 0 ou scannez le QR code dans la chambre. Besoin de quelque chose ? Répondez simplement. Bon séjour à ' + CITY + ' !',
  es: '¡Bienvenido' + guest + '! Su habitación ' + room + ' está lista. Salida: ' + date + '. Wi-Fi y código de puerta: en el portal del huésped ' + PORTAL + '. Servicio de habitaciones: marque 0 o escanee el código QR de la habitación. ¿Necesita algo? Responda aquí. ¡Disfrute su estancia en ' + CITY + '!',
  it: 'Benvenuto' + guest + '! La sua camera ' + room + ' è pronta. Check-out: ' + date + '. Wi-Fi e codice porta: nel portale ospiti ' + PORTAL + '. Servizio in camera: componga 0 o scansioni il QR in camera. Ha bisogno di qualcosa? Risponda pure. Buon soggiorno a ' + CITY + '!',
  uk: 'Вітаємо' + guest + '! Ваш номер ' + room + ' готовий. Виїзд: ' + date + '. Wi-Fi і код від дверей: у порталі гостя ' + PORTAL + '. Обслуговування номерів: наберіть 0 або скануйте QR-код у номері. Потрібна допомога? Напишіть. Приємного перебування у ' + CITY + '!',
};
const order = ['en','pl','de','fr','es','it','uk'];
const allLanguages = order.map(l => T[l]).join('\n\n──────────\n\n');
return [{ json: { event: b.event, room, guest: d.guest || '', checkoutDate: date, localized: T, allLanguages, summary: T.en } }];
